CREATE TABLE p(a,b,PRIMARY KEY(a,b)); CREATE TABLE c1(c,d,FOREIGN KEY(c,d) REFERENCES p ON DELETE SET NULL); CREATE TABLE c2(c,d,FOREIGN KEY(c,d) REFERENCES p ON DELETE SET DEFAULT); CREATE TABLE c3(c,d,FOREIGN KEY(c,d) REFERENCES p ON DELETE CASCADE); INSERT INTO p VALUES('a','b'); INSERT INTO c1 VALUES('a','b'); INSERT INTO c2 VALUES('a','b'); INSERT INTO c3 VALUES('a','b');